 async function exportExcel(s){
  if(!live(s)||s.busy||!s.plan)return;
  const plan=model().copyValidated(s.plan),ticket=s.loadTicket,unsaved=s.dirty;
  busy(s,true,'Preparing Excel…');
  try{
   model().validate(plan);
   let baseline=s.ctx.cachedTimetable?.(plan.date);
   if(!baseline&&s.ctx.localTimetable)baseline=await s.ctx.localTimetable(plan.date);
   if(!live(s)||s.loadTicket!==ticket)return;
   if(baseline?.modelId!==plan.baselineId){baseline=null;if(plan.baselineId&&!/^standalone:/.test(plan.baselineId)){try{baseline=await s.ctx.api('read',{id:plan.baselineId,date:plan.date,calendar:false});}catch(error){baseline=null;}}}
   if(window.RosterStaplerExport.canUseBaseline&&!window.RosterStaplerExport.canUseBaseline(plan,baseline))baseline=null;
   if(!live(s)||s.loadTicket!==ticket)return;
   const book=await window.RosterStaplerExport.makeWorkbook(plan,baseline,{eventName:s.data.eventName||'Stapler',includeClassPov:true});
   if(!live(s)||s.loadTicket!==ticket)return;
   const url=URL.createObjectURL(book.blob),link=document.createElement('a');
   link.href=url;link.download=book.filename;document.body.append(link);link.click();link.remove();
   setTimeout(()=>URL.revokeObjectURL(url),5000);
   tell(s,'Excel exported for '+plan.date+'.'+(!baseline?' Selected date only; the original weekly source is unavailable or incompatible.':'')+(unsaved?' It includes your unsaved changes.':''));
  }catch(error){if(live(s)&&s.loadTicket===ticket)tell(s,(error.message||'Excel export failed.')+' Use Export Excel to retry.',true);}
  finally{if(live(s))busy(s,false);}
 }
